// File: varacore/tests/stress_tests.rs
// Additional edge case stress tests generated by hackathon-stress phase.
// Tests gaps not covered by oracle_tests.rs / reputation_tests.rs / registry_tests.rs.
use gtest::{Program, System};
use parity_scale_codec::Encode;

fn init_varacore(sys: &System) -> Program {
    sys.mint_to(42u64, 1_000_000_000_000_000_u128);
    sys.mint_to(100u64, 1_000_000_000_000_000_u128);
    sys.mint_to(101u64, 1_000_000_000_000_000_u128);
    let program = Program::current(sys);
    let init_id = program.send_bytes(42u64, "New".encode());
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&init_id),
        "VaraCore init failed. failed={:?}",
        result.failed
    );
    program
}

fn agent_actor_id(user: u64) -> [u8; 32] {
    let mut id = [0u8; 32];
    id[..8].copy_from_slice(&user.to_le_bytes());
    id
}

// ─────────────── Oracle edge cases ───────────────

/// ST-F1-EDGE-02: source_count=0 → Err("source_count must be >= 1")
#[test]
fn test_update_price_source_count_zero_rejected() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    let payload = (
        "Oracle", "UpdatePrice",
        "VARA/USD",
        100_000_000u128, // valid non-zero price
        0u128,
        1_716_400_000u64,
        0u32, // source_count = 0 → should fail
    ).encode();
    let msg_id = program.send_bytes(42u64, payload);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "UpdatePrice(source_count=0) panicked — should return Err not panic. failed={:?}",
        result.failed
    );
}

/// ST-F1-EDGE-05: source_count=1 → status=Degraded but Ok(())
#[test]
fn test_update_price_source_count_one_returns_degraded() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    let payload = (
        "Oracle", "UpdatePrice",
        "ETH/USD",
        200_000_000_000u128, // $2000 in 8dp
        5_000_000_000u128,
        1_716_400_000u64,
        1u32, // single source → Degraded status
    ).encode();
    let msg_id = program.send_bytes(42u64, payload);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "UpdatePrice(source_count=1) failed. failed={:?}",
        result.failed
    );
    // Follow up with GetPrice — message should succeed
    let get_payload = ("Oracle", "GetPrice", "ETH/USD").encode();
    let msg_id2 = program.send_bytes(42u64, get_payload);
    let result2 = sys.run_next_block();
    assert!(
        result2.succeed.contains(&msg_id2),
        "GetPrice after Degraded update failed. failed={:?}",
        result2.failed
    );
}

