/// ST-CON-03: TWAP ring buffer wraps correctly after 10 updates (ring size = 8)
#[test]
fn test_twap_ring_buffer_wraps_at_eight() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    for i in 0u64..10 {
        let price = 100_000_000u128 + (i as u128 * 1_000_000u128);
        let payload = (
            "Oracle", "UpdatePrice",
            "DOT/USD",
            price,
            1_000_000u128,
            1_716_400_000u64 + i,
            3u32,
        ).encode();
        let msg_id = program.send_bytes(42u64, payload);
        let result = sys.run_next_block();
        assert!(
            result.succeed.contains(&msg_id),
            "UpdatePrice iteration {} panicked. failed={:?}", i, result.failed
        );
    }
    // GetPrice after 10 updates — should still return a valid price (no panic from ring overflow)
    let get_payload = ("Oracle", "GetPrice", "DOT/USD").encode();
    let msg_id = program.send_bytes(42u64, get_payload);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "GetPrice after 10-update TWAP ring wrap failed. failed={:?}",
        result.failed
    );
}

/// ST-F1-FUNC-04: GetMultiplePrices with mix of valid and unknown assets
#[test]
fn test_get_multiple_prices_mixed() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    // Seed one asset
    program.send_bytes(42u64, (
        "Oracle", "UpdatePrice",
        "VARA/USD",
        64_000u128,
        1_000u128,
        1_716_400_000u64,
        2u32,
    ).encode());
    sys.run_next_block();

    // Query two assets: one seeded, one not
    let assets: Vec<String> = vec!["VARA/USD".to_string(), "UNKNOWN/USD".to_string()];
    let payload = ("Oracle", "GetMultiplePrices", assets).encode();
    let msg_id = program.send_bytes(42u64, payload);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "GetMultiplePrices mixed assets panicked. failed={:?}",
        result.failed
    );
}

