/// ST-F3-EDGE-02: RecordInteraction with 257-char context — succeeds, truncated to 256
#[test]
fn test_record_interaction_long_context_truncated() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    let long_context: String = "x".repeat(257);
    let agent_id = [5u8; 32];
    let payload = ("Reputation", "RecordInteraction", agent_id, true, long_context.as_str()).encode();
    let msg_id = program.send_bytes(42u64, payload);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "RecordInteraction(257-char context) failed. failed={:?}",
        result.failed
    );
    // GetInteractionHistory — the message must succeed (history is non-empty)
    let hist_payload = ("Reputation", "GetInteractionHistory", agent_id, 1u32).encode();
    let msg_id2 = program.send_bytes(42u64, hist_payload);
    let result2 = sys.run_next_block();
    assert!(
        result2.succeed.contains(&msg_id2),
        "GetInteractionHistory after long context failed. failed={:?}",
        result2.failed
    );
}

/// ST-F3-EDGE-03: 51 interactions — history cap = 50, FIFO eviction
#[test]
fn test_interaction_history_capped_at_50() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    let agent_id = [6u8; 32];
    for i in 0u32..51 {
        let ctx = alloc::format!("interaction-{}", i);
        let payload = ("Reputation", "RecordInteraction", agent_id, true, ctx.as_str()).encode();
        let msg_id = program.send_bytes(42u64, payload);
        let result = sys.run_next_block();
        assert!(
            result.succeed.contains(&msg_id),
            "RecordInteraction {} failed. failed={:?}", i, result.failed
        );
    }
    // GetInteractionHistory limit=100 — should succeed and return at most 50 records
    let hist_payload = ("Reputation", "GetInteractionHistory", agent_id, 100u32).encode();
    let msg_id = program.send_bytes(42u64, hist_payload);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "GetInteractionHistory after 51 interactions failed. failed={:?}",
        result.failed
    );
}

/// ST-F3-EDGE-07: ScoreAgent after only failures — score should be low but > 0 (has interactions)
#[test]
fn test_score_agent_all_failures() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    let agent_id = [7u8; 32];
    for _ in 0..5 {
        let payload = ("Reputation", "RecordInteraction", agent_id, false, "fail").encode();
        let msg_id = program.send_bytes(42u64, payload);
        let result = sys.run_next_block();
        assert!(
            result.succeed.contains(&msg_id),
            "RecordInteraction(false) failed."
        );
    }
    // ScoreAgent — should succeed and return data (not Err, since interactions were recorded)
    let payload = ("Reputation", "ScoreAgent", agent_id).encode();
    let msg_id = program.send_bytes(42u64, payload);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "ScoreAgent after all-failure interactions panicked. failed={:?}",
        result.failed
    );
}

