/// ST-F4-EDGE-03: HeartbeatAgent wrong caller → Err (SEC-001)
#[test]
fn test_heartbeat_wrong_caller_returns_err() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    // Register agent as user 100
    let reg_payload = (
        "Registry", "RegisterAgent",
        "user100", vec!["oracle"], 0u8, "desc", "http://x.com",
    ).encode();
    program.send_bytes(100u64, reg_payload);
    sys.run_next_block();

    // Alice (user 42) tries to send heartbeat for user 100's actor_id → Err
    let agent_id = agent_actor_id(100);
    let payload = ("Registry", "HeartbeatAgent", agent_id).encode();
    let msg_id = program.send_bytes(42u64, payload); // 42 != 100
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "HeartbeatAgent(wrong caller) panicked — should return Err. failed={:?}",
        result.failed
    );
}

