/// ST-CON-05: Re-register updates capability index — old caps removed, new caps indexed
#[test]
fn test_reregister_updates_capability_index() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    // Register with cap "cap-a"
    let reg1 = (
        "Registry", "RegisterAgent",
        "my-agent", vec!["cap-a"], 0u8, "desc", "http://x.com",
    ).encode();
    program.send_bytes(100u64, reg1);
    sys.run_next_block();

    // Re-register with cap "cap-b" (replaces cap-a)
    let reg2 = (
        "Registry", "RegisterAgent",
        "my-agent-v2", vec!["cap-b"], 0u8, "desc-updated", "http://x.com",
    ).encode();
    let msg_id = program.send_bytes(100u64, reg2);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "Re-register failed. failed={:?}",
        result.failed
    );

    // GetAgentsByCapability("cap-a") — agent should NOT appear (old caps removed from index)
    let q1 = ("Registry", "GetAgentsByCapability", "cap-a").encode();
    let msg_id2 = program.send_bytes(42u64, q1);
    let result2 = sys.run_next_block();
    assert!(
        result2.succeed.contains(&msg_id2),
        "GetAgentsByCapability(cap-a) after re-register panicked. failed={:?}",
        result2.failed
    );

    // GetAgentsByCapability("cap-b") — agent SHOULD appear
    let q2 = ("Registry", "GetAgentsByCapability", "cap-b").encode();
    let msg_id3 = program.send_bytes(42u64, q2);
    let result3 = sys.run_next_block();
    assert!(
        result3.succeed.contains(&msg_id3),
        "GetAgentsByCapability(cap-b) after re-register panicked. failed={:?}",
        result3.failed
    );
}

/// ST-CON-04: Delist removes agent from capability index
#[test]
fn test_delist_removes_from_capability_index() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    // Register with cap "price-feed"
    let reg = (
        "Registry", "RegisterAgent",
        "my-agent", vec!["price-feed"], 0u8, "desc", "http://x.com",
    ).encode();
    program.send_bytes(100u64, reg);
    sys.run_next_block();

    // Delist as user 100
    let agent_id = agent_actor_id(100);
    let delist = ("Registry", "DelistAgent", agent_id).encode();
    let msg_id = program.send_bytes(100u64, delist);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "DelistAgent failed. failed={:?}",
        result.failed
    );

    // GetAgentsByCapability("price-feed") — should return empty (agent delisted)
    let q = ("Registry", "GetAgentsByCapability", "price-feed").encode();
    let msg_id2 = program.send_bytes(42u64, q);
    let result2 = sys.run_next_block();
    assert!(
        result2.succeed.contains(&msg_id2),
        "GetAgentsByCapability after delist panicked. failed={:?}",
        result2.failed
    );
}

/// ST-CON-06: 2 agents same capability — both returned
#[test]
fn test_two_agents_same_capability_both_returned() {
    let sys = System::new();
    sys.init_logger();
    let program = init_varacore(&sys);

    let reg_a = (
        "Registry", "RegisterAgent",
        "agent-a", vec!["shared-cap"], 0u8, "a", "http://a.com",
    ).encode();
    program.send_bytes(100u64, reg_a);
    sys.run_next_block();

    let reg_b = (
        "Registry", "RegisterAgent",
        "agent-b", vec!["shared-cap"], 0u8, "b", "http://b.com",
    ).encode();
    program.send_bytes(101u64, reg_b);
    sys.run_next_block();

    let q = ("Registry", "GetAgentsByCapability", "shared-cap").encode();
    let msg_id = program.send_bytes(42u64, q);
    let result = sys.run_next_block();
    assert!(
        result.succeed.contains(&msg_id),
        "GetAgentsByCapability(shared-cap) with 2 agents panicked. failed={:?}",
        result.failed
    );
}

